#!/usr/bin/env python3
"""One-time materializer for the remaining issue #7 first-class port contracts."""
from __future__ import annotations
import base64
import io
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARCHIVE = """"""

with tarfile.open(fileobj=io.BytesIO(base64.b64decode(ARCHIVE)), mode="r:gz") as archive:
    for member in archive.getmembers():
        target = (ROOT / member.name).resolve()
        target.relative_to(ROOT)
    archive.extractall(ROOT)

print("Materialized 21 remaining first-class port contracts.")
